function SiteForm({ position, userId, onClose, onSiteAdded }) {
  // ... existing state ...

  const handleSubmit = async (e) => {
    e.preventDefault()
    setUploading(true)
    try {
      let photoUrl = null

      if (photo) {
        const ext = photo.name.split('.').pop()
        const fileName = `${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`
        const { error: uploadError } = await supabase
          .storage.from('site-photos').upload(fileName, photo, { upsert: false })
        if (uploadError) throw uploadError

        const { data } = supabase.storage.from('site-photos').getPublicUrl(fileName)
        photoUrl = data.publicUrl
      }

      const { data, error } = await supabase
        .from('derelict_sites')
        .insert([{
          name,
          description,
          latitude: position.lat,
          longitude: position.lng,
          photo_url: photoUrl,
          user_id: userId  // <-- ADD THIS
        }])
        .select(`
          *,
          profiles:user_id (username, avatar_url)
        `)

      if (error) throw error
      onSiteAdded(data[0])
      onClose()
    } catch (err) {
      console.error(err)
      alert('Error adding site: ' + err.message)
    } finally {
      setUploading(false)
    }
  }

  // ... rest of component stays the same ...
}
